using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

// 1. Get strongly-typed metadata — returns JsonTypeInfo<T> directly
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"Got typed metadata for: {personInfo.Type.Name}");

// Round-trip to prove it works
var json = JsonSerializer.Serialize(new Person("Ada", 36), personInfo);
Console.WriteLine($"Serialized: {json}");
Person p = JsonSerializer.Deserialize(json, personInfo)!;
Console.WriteLine($"Deserialized: {p}");

// 2. Probe without throwing — TryGetTypeInfo returns false if unavailable
if (options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? found))
    Console.WriteLine($"\nTryGetTypeInfo(Person) succeeded: {found!.Type.Name}");

// For a type that hasn't been resolved (use a restrictive resolver to demonstrate)
var strict = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver
    {
        Modifiers = { (info) => {
            if (info.Type == typeof(Secret))
                throw new NotSupportedException("Secret is not allowed");
        }}
    }
};

if (!strict.TryGetTypeInfo(typeof(Secret), out _))
    Console.WriteLine("TryGetTypeInfo(Secret) returned false — no exception thrown.");

record Person(string Name, int Age);
record Secret(string Value);

