// For a type the resolver simply can't resolve (returns null)
var strict = new JsonSerializerOptions
{
    TypeInfoResolver = JsonTypeInfoResolver.Combine(
        // A custom resolver that only handles Person
        new PersonOnlyResolver())
};

if (strict.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? p2))
    Console.WriteLine($"TryGetTypeInfo(Person) on strict: found ({p2!.Type.Name})");

if (!strict.TryGetTypeInfo(typeof(Secret), out _))
    Console.WriteLine("TryGetTypeInfo(Secret) returned false — no exception thrown.");

record Person(string Name, int Age);
record Secret(string Value);

// A resolver that only resolves Person, returns null for anything else
sealed class PersonOnlyResolver : IJsonTypeInfoResolver
{
    private readonly DefaultJsonTypeInfoResolver _inner = new();

    public JsonTypeInfo? GetTypeInfo(Type type, JsonSerializerOptions options)
    {
        if (type == typeof(Person))
            return _inner.GetTypeInfo(type, options);
        return null; // signals "not available"
    }
}

